.darma-loader-darma-b12-zipper-pull::before { top: 4%; }
.darma-loader-darma-b12-zipper-pull::after { bottom: 4%; }
.darma-loader-darma-b12-zipper-pull span { position: absolute; left: 0; top: 30%; height: 40%; width: 6%; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--accent) 0 var(--tooth), var(--accent-2) var(--tooth) calc(var(--tooth) * 2)); animation: darma-loader-darma-b12-zipper-pull-zip calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b12-zipper-pull .darma-loader-darma-b12-zipper-pull__slider { position: absolute; z-index: 3; left: 0; top: 14%; width: 13%; height: 72%; border-radius: 3px; background: linear-gradient(var(--accent-2), var(--accent)); box-shadow: 0 2px 5px rgba(15, 23, 42, .28); animation: darma-loader-darma-b12-zipper-pull-pull calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b12-zipper-pull .darma-loader-darma-b12-zipper-pull__slider::after { content: ''; position: absolute; top: 90%; left: 28%; width: 44%; height: 58%; border-radius: 0 0 5px 5px; background: var(--accent); }
@keyframes darma-loader-darma-b12-zipper-pull-zip { 0% { width: 6%; } 58% { width: 100%; } 100% { width: 6%; } }
